import{_ as e,o as t,c as p,ac as a}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十三次全国代表大会选举办法","description":"","frontmatter":{"prev":{"text":"沿着有中国特色的社会主义道路前进——赵紫阳在中国共产党第十三次全国代表大会上的报告","link":"./沿着有中国特色的社会主义道路前进"},"next":{"text":"中央顾问委员会向党的第十三次全国代表大会的工作报告","link":"./中央顾问委员会向党的第十三次全国代表大会的工作报告"}},"headers":[],"relativePath":"13/中国共产党第十三次全国代表大会选举办法.md","filePath":"13/中国共产党第十三次全国代表大会选举办法.md"}'),r={name:"13/中国共产党第十三次全国代表大会选举办法.md"};function n(o,_,s,i,c,l){return t(),p("div",null,[..._[0]||(_[0]=[a('<h1 id="中国共产党第十三次全国代表大会选举办法" tabindex="-1">中国共产党第十三次全国代表大会选举办法 <a class="header-anchor" href="#中国共产党第十三次全国代表大会选举办法" aria-label="Permalink to &quot;中国共产党第十三次全国代表大会选举办法&quot;">​</a></h1><p><em>（1987年10月27日中国共产党第十三次全国代表大会主席团第二次会议通过）</em></p><p>  一、第十三届中央委员会、中央顾问委员会和中央纪律检查委员会均由党的全国代表大会选举产生。选举的组织工作，由大会主席团负责。</p><p>  二、大会选举采用无记名投票方式。候选人按照姓氏笔划为序排列。中央委员会委员、中央委员会候补委员、中央纪律检查委员会委员采用差额选举的办法产生，中央顾问委员会委员采用等额选举的办法产生。</p><p>  三、第十三届中央委员会委员、中央委员会候补委员、中央顾问委员会委员、中央纪律检查委员会委员候选人预备名单，由第十二届中央政治局提出，经大会主席团审议后，提交各代表团酝酿。代表团汇总各方面意见（包括提出新增人选）后，交大会主席团认真研究，确定候选人预选名单，提交大会进行预选。</p><p>  四、中央委员、中央候补委员和中央纪律检查委员会委员候选人经差额预选产生。中央委员、中央纪律检查委员会委员候选人的差额不少于预提候选人数的5%，中央候补委员候选人的差额不少于预提候选人数的12%。差额预选分两次进行，即先进行中央委员、中央纪律检查委员会委员候选人的预选，然后进行中央候补委员候选人的预选。中央委员候选人落选的，列入中央候补委员候选人预选名单，参加中央候补委员候选人的预选。差额预选以代表团为单位分别投票，由大会统一计票。大会主席团常务委员会按照差额预选的结果，研究提出候选人名单，再提交各代表团讨论确定。</p><p>  五、中央委员会、中央顾问委员会和中央纪律检查委员会的正式选举，分四张选票，即中央委员、中央候补委员、中央顾问委员会委员、中央纪律检查委员会委员各一张选票，在同一票箱依次投票，分别计票，一次宣布选举结果。</p><p>  六、在预选和正式选举时，参加选举的代表必须超过应到会代表（含特邀代表）的半数，方可进行选举；收回的选票等于或少于发出的选票，选举有效；收回的选票多于发出的选票，选举无效，应重新进行选举。正式选举时，等额选举，候选人得到的赞成票超过应到会议代表的半数为当选。</p><p>  七、大会宣布选举结果时，中央委员、中央顾问委员会委员、中央纪律检查委员会委员按姓氏笔划为序排列，中央候补委员按得票多少为序排列，并报告所得票数。对外公布名单时，中央委员、中央顾问委员会委员、中央纪律检查委员会委员按姓氏笔划为序排列，中央候补委员按得票多少为序排列。</p><p>  八、本次会议选举采用电子计算机计票。请与会代表严格按照规定的办法写票和投票。如计票系统出现意外故障，投票继续进行，改由大会工作人员计票。</p><p>  九、大会选举设监票人33名，其中总监票人2名。监票人和总监票人经大会选举产生。已提名作为中央委员、中央候补委员、中央顾问委员会委员和中央纪律检查委员会委员候选人的同志不得担任监票人。监票人在大会主席团领导下，对选举全过程进行监督。计票工作人员由大会秘书处指定，在监票人领导下进行工作。</p><p>  十、由于技术上的原因，本次会议选举不设流动票箱。请假的代表不参加投票。</p><p>  十一、本选举办法，经大会主席团全体会议通过生效。</p>',13)])])}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
